css:
*,*::before,*::after{box-sizing:border-box}
html{-webkit-text-size-adjust:100%}
body{margin:0;background:#f7f5f1;color:#1c1b18;font-family:-apple-system,BlinkMacSystemFont,'PingFang SC','Hiragino Sans GB','Microsoft YaHei',sans-serif;font-size:16px;line-height:1.7}
img{display:block;max-width:100%;height:auto}
a{color:#a8321c}
a:hover{color:#8c2915}
:focus-visible{outline:2px solid #a8321c;outline-offset:2px}
h1,h2,h3{line-height:1.25;font-weight:700;letter-spacing:-.01em}
h1{font-size:clamp(1.85rem,4.6vw,3.3rem);margin:0 0 18px}
h2{font-size:clamp(1.3rem,2.3vw,1.75rem);margin:0 0 14px}
h3{font-size:1.02rem;margin:0 0 8px}
p{margin:0 0 14px;max-width:38em}
figure{margin:0}
figcaption{font-size:.85rem;color:#5a574f;padding-top:8px}
.wrap{width:100%;max-width:1180px;margin:0 auto;padding:0 24px}

.site-header{border-bottom:1px solid #d7d1c6;background:#f7f5f1}
.header-inner{display:flex;align-items:center;gap:28px;min-height:68px}
.brand{font-weight:700;font-size:1.05rem;color:#1c1b18;text-decoration:none}
.brand:hover{color:#1c1b18}
.site-nav{display:flex;gap:24px;margin-left:auto;font-size:.95rem}
.site-nav a{color:#3a3833;text-decoration:none;padding:4px 0;border-bottom:2px solid transparent}
.site-nav a:hover{color:#1c1b18;border-bottom-color:#a8321c}

.btn{display:inline-block;padding:14px 24px;border-radius:2px;border:1px solid transparent;font-weight:600;font-size:.95rem;line-height:1.2;text-decoration:none}
.btn-primary{background:#a8321c;color:#fff}
.btn-primary:hover{background:#8c2915;color:#fff}
.btn-outline{border-color:#1c1b18;color:#1c1b18}
.btn-outline:hover{border-color:#a8321c;color:#a8321c}
.header-cta{padding:11px 18px;font-size:.88rem}

.hero{padding:76px 0 34px}
.hero-lede{font-size:clamp(1.02rem,1.5vw,1.18rem);color:#45433d;max-width:32em}
.hero-actions{display:flex;flex-wrap:wrap;gap:18px;align-items:center;margin-top:26px}
.link-quiet{color:#1c1b18;text-decoration:underline;text-underline-offset:3px}
.link-quiet:hover{color:#a8321c}

.fig-wide{margin-top:26px}
.fig-wide img{width:100%;aspect-ratio:16/6;object-fit:cover}
.fig-block img{width:100%;aspect-ratio:16/9;object-fit:cover}
.fig-block figcaption{padding-top:8px;padding-bottom:22px}
.fig-side img{width:100%;aspect-ratio:4/3;object-fit:cover}

.band{padding:56px 0}
.band-tight{padding:40px 0 64px}
.band-dark{background:#1d1c19;color:#f2efe8}
.band-dark h2{color:#f2efe8}
.band-dark p{color:#d8d3c9}

.stat-row{margin:0;display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid #d7d1c6}
.stat{padding:22px 26px 24px 0}
.stat+.stat{padding-left:26px;border-left:1px solid #d7d1c6}
.stat dt{font-size:.85rem;color:#5a574f;margin-bottom:6px}
.stat dd{margin:0;font-size:clamp(1.15rem,1.8vw,1.4rem);font-weight:700;font-variant-numeric:tabular-nums;letter-spacing:-.01em}
.band-dark .stat-row{border-bottom-color:#3a3833}
.band-dark .stat+.stat{border-left-color:#3a3833}
.band-dark .stat dt{color:#b9b3a8}
.band-dark .stat dd{color:#f2efe8}

.prod-list{list-style:none;margin:22px 0 0;padding:0;border-top:1px solid #d7d1c6}
.prod-list li{display:grid;grid-template-columns:minmax(170px,230px) 1fr;gap:24px;padding:18px 0;border-bottom:1px solid #d7d1c6;align-items:baseline}
.p-name{font-weight:600;font-size:1.02rem;color:#1c1b18;text-decoration:none}
.p-name:hover{color:#a8321c}
.p-name [data-system-icon]{margin-left:8px;color:#a8321c}
.p-desc{color:#45433d;font-size:.95rem;font-variant-numeric:tabular-nums}

.cols-2{display:grid;grid-template-columns:1fr 1fr;gap:56px}
.list-plain{list-style:none;margin:0;padding:0}
.list-plain li{display:flex;justify-content:space-between;gap:16px;padding:10px 0;border-bottom:1px solid #d7d1c6;font-variant-numeric:tabular-nums}
.list-plain .qty{color:#45433d}
.list-inline{list-style:none;margin:0;padding:0;display:flex;flex-wrap:wrap;gap:10px 28px}
.list-inline li{color:#45433d;font-variant-numeric:tabular-nums}

.timeline{margin:0}
.timeline>div{display:grid;grid-template-columns:96px 1fr;gap:24px;padding:14px 0;border-top:1px solid #d7d1c6}
.timeline dt{font-weight:700;color:#a8321c;font-variant-numeric:tabular-nums}
.timeline dd{margin:0;color:#45433d}

.steps{list-style:none;margin:0;padding:0}
.steps li{display:grid;grid-template-columns:52px 1fr;gap:18px;padding:16px 0;border-top:1px solid #d7d1c6;align-items:baseline}
.step-no{font-weight:700;color:#a8321c;font-variant-numeric:tabular-nums}
.steps h3{margin:0}

.faq{margin:0;max-width:56em}
.faq>div{padding:22px 0;border-top:1px solid #d7d1c6}
.faq dt{font-weight:700;font-size:1.08rem;margin-bottom:8px}
.faq dd{margin:0;color:#45433d}

.fact-list{margin:0;max-width:44em}
.fact-list>div{display:grid;grid-template-columns:120px 1fr;gap:20px;padding:14px 0;border-top:1px solid #d7d1c6}
.fact-list dt{color:#45433d;font-size:.92rem}
.fact-list dd{margin:0;font-variant-numeric:tabular-nums}

.page-head{padding:64px 0 8px}
.lede{font-size:clamp(1rem,1.4vw,1.15rem);color:#45433d;max-width:34em}

.spec{width:100%;border-collapse:collapse;margin:0}
.spec th,.spec td{text-align:left;vertical-align:top;padding:11px 16px 11px 0;border-bottom:1px solid #d7d1c6;font-size:.95rem;font-variant-numeric:tabular-nums;word-break:break-word}
.spec th{width:34%;font-weight:600;color:#45433d}
.spec-block{padding:44px 0}
.spec-block+.spec-block{border-top:1px solid #d7d1c6}
.spec-end{padding-bottom:72px}
.spec-split{display:grid;grid-template-columns:1.1fr .9fr;gap:48px;align-items:start}
.note{color:#45433d;font-size:.95rem;margin-top:18px}

.site-footer{background:#1d1c19;color:#f2efe8}
.footer-grid{display:grid;grid-template-columns:1.5fr 1fr 1.2fr;gap:48px;padding:56px 24px 40px}
.footer-name{margin:0 0 12px;font-weight:700;font-size:1.1rem;color:#f2efe8}
.footer-text{color:#c9c3b8;font-size:.92rem;margin:0;max-width:30em}
.footer-nav{display:flex;flex-direction:column;gap:10px}
.footer-nav a{color:#f2efe8;text-decoration:none;font-size:.95rem}
.footer-nav a:hover{color:#e8a68f;text-decoration:underline}
.footer-info p{color:#c9c3b8;font-size:.92rem;margin:0 0 10px}
.footer-info a{color:#f2efe8;text-decoration:underline;text-underline-offset:2px}
.footer-info a:hover{color:#e8a68f}
.footer-base{border-top:1px solid #3a3833;padding:20px 24px 28px}
.footer-base p{margin:0;color:#b9b3a8;font-size:.85rem}

@media (max-width:900px){
  .spec-split{grid-template-columns:1fr;gap:24px}
}
@media (max-width:768px){
  .wrap{padding:0 18px}
  .header-inner{gap:14px;padding:12px 18px}
  .site-nav{order:3;width:100%;margin-left:0;gap:18px;padding-top:10px;border-top:1px solid #d7d1c6;font-size:.9rem}
  .header-cta{margin-left:auto;padding:9px 14px;font-size:.82rem}
  .hero{padding:48px 0 26px}
  .band{padding:40px 0}
  .band-tight{padding:32px 0 52px}
  .fig-wide img{aspect-ratio:16/10}
  .fig-block img{aspect-ratio:4/3}
  .stat-row{grid-template-columns:1fr 1fr}
  .stat{padding:16px 14px 18px 0}
  .stat+.stat{padding-left:14px}
  .stat:nth-child(odd){padding-left:0;border-left:0}
  .stat:nth-child(n+3){border-top:1px solid #d7d1c6}
  .band-dark .stat:nth-child(n+3){border-top-color:#3a3833}
  .stat dd{font-size:1.05rem}
  .prod-list li{grid-template-columns:1fr;gap:6px}
  .cols-2{grid-template-columns:1fr;gap:32px}
  .timeline>div{grid-template-columns:72px 1fr;gap:16px}
  .fact-list>div{grid-template-columns:1fr;gap:2px}
  .steps li{grid-template-columns:40px 1fr;gap:12px}
  .page-head{padding:44px 0 8px}
  .footer-grid{grid-template-columns:1fr;gap:32px;padding:40px 18px 32px}
  .footer-base{padding:18px 18px 26px}
}
